usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Evals.Runs.OutputItems.Get(context.TODO(), "eval_id", "run_id", "output_item_id")
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
